#!/usr/bin/env bash
# The hook files in hooks/ and their mirror in plugins/belt/hooks/ are
# generated by the belt CLI: `belt plugin render-hooks <agent>` prints the
# hook file belt installs for that agent, from the same code `belt plugin
# install` and the agentprotocol conformance suite run. Do not edit them by
# hand; change belt's plugin source (inference-sh/cli internal/beltplugin) or
# the agent's entry in agentprotocol/harness, then run this script.
#
#   ./.github/scripts/generate-hooks.sh          rewrite the files
#   ./.github/scripts/generate-hooks.sh --check  fail if any file is stale
#
# BELT selects the belt binary (default: belt on PATH).
#
# plugins/belt/hooks/codex-hooks.json is not generated: the Codex plugin
# manifest loads it and it still calls the plugin's bin/ scripts.

set -euo pipefail
cd "$(dirname "$0")/../.."

BELT="${BELT:-belt}"
CHECK=0
[[ "${1:-}" == "--check" ]] && CHECK=1

# <file in hooks/>:<agent>. hooks.json is the file Claude Code loads from the
# plugin; claude.json is the same content for a manual settings.json merge.
FILES=(
  hooks.json:claude
  claude.json:claude
  codex.json:codex
  copilot.json:copilot
  cursor.json:cursor
  droid.json:droid
  gemini.json:gemini
  goose.json:goose
  grok.json:grok
  hermes.yaml:hermes
  kilo.ts:kilo
  kimi.toml:kimi
  opencode.ts:opencode
  pi.ts:pi
  qwen.json:qwen
  windsurf.json:windsurf
)

if ! "$BELT" plugin render-hooks claude >/dev/null 2>&1; then
  echo "error: '$BELT plugin render-hooks' is not available; update the belt CLI" >&2
  exit 2
fi

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
stale=0

for entry in "${FILES[@]}"; do
  file="${entry%%:*}"
  agent="${entry##*:}"
  out="$tmp/$file"
  if [[ "$file" == *.json ]]; then
    "$BELT" plugin render-hooks "$agent" 2>/dev/null | jq . > "$out"
  else
    "$BELT" plugin render-hooks "$agent" 2>/dev/null > "$out"
    # End with exactly one newline.
    printf '%s\n' "$(cat "$out")" > "$out"
  fi
  for dest in "hooks/$file" "plugins/belt/hooks/$file"; do
    if (( CHECK )); then
      if ! cmp -s "$out" "$dest"; then
        echo "stale: $dest" >&2
        diff -u "$dest" "$out" | head -40 >&2 || true
        stale=1
      fi
    else
      cp "$out" "$dest"
    fi
  done
done

if (( CHECK )); then
  if (( stale )); then
    echo >&2
    echo "hook files differ from what the belt CLI generates." >&2
    echo "run ./.github/scripts/generate-hooks.sh and commit the result." >&2
    exit 1
  fi
  echo "hook files match what the belt CLI generates."
fi
